'use strict';

/**
 * Release build step: minifies the plain, hand-edited frontend/admin
 * CSS/JS files into `.min.css`/`.min.js` build artifacts.
 *
 * This is deliberately NOT part of local development — see AGENTS.md
 * ("no build step" for both assets/cookie-notice/ and assets/admin/).
 * Contributors keep editing the plain files directly; `.min.*` outputs are
 * only ever consumed at runtime (see CookieNotice::get_asset_url() and
 * Settings::get_asset_url()) when SCRIPT_DEBUG is off AND the minified file
 * happens to exist, and are only ever generated by:
 *   - `npm run build`, run manually by anyone who wants to test the
 *     minified path locally, or
 *   - the "Deploy to WordPress.org" GitHub Actions workflow, right before
 *     packaging a tagged release.
 *
 * A fresh checkout that never runs this script keeps working exactly as
 * before: the PHP enqueue helpers fall back to the plain files whenever the
 * `.min.*` counterpart is missing.
 *
 * @package FrontConsent
 */

const fs = require( 'fs' );
const path = require( 'path' );
const { minify: terserMinify } = require( 'terser' );
const CleanCSS = require( 'clean-css' );

/**
 * Plugin-relative paths of every plain asset this script knows how to
 * minify. Keep in sync with the enqueue calls in includes/Frontend/CookieNotice.php
 * and includes/Admin/Settings.php.
 */
const ASSETS = [
	{ relativePath: 'assets/cookie-notice/frontconsent-cookie-notice.js', type: 'js' },
	{ relativePath: 'assets/cookie-notice/frontconsent-cookie-notice.css', type: 'css' },
	{ relativePath: 'assets/admin/settings.js', type: 'js' },
	{ relativePath: 'assets/admin/settings.css', type: 'css' },
];

/**
 * Minify a single JS source string with Terser.
 *
 * @param {string} source Plain JS source.
 * @return {Promise<string>} Minified JS.
 */
async function minifyJs( source ) {
	const result = await terserMinify( source, {
		compress: true,
		mangle: true,
	} );

	if ( ! result || typeof result.code !== 'string' || result.code.length === 0 ) {
		throw new Error( 'Terser produced no output.' );
	}

	return result.code;
}

/**
 * Minify a single CSS source string with clean-css.
 *
 * @param {string} source Plain CSS source.
 * @return {string} Minified CSS.
 */
function minifyCss( source ) {
	const output = new CleanCSS( { level: 2 } ).minify( source );

	if ( output.errors && output.errors.length > 0 ) {
		throw new Error( 'clean-css failed: ' + output.errors.join( '; ' ) );
	}

	if ( typeof output.styles !== 'string' || output.styles.length === 0 ) {
		throw new Error( 'clean-css produced no output.' );
	}

	return output.styles;
}

/**
 * Turn a plain asset's relative path into its `.min.*` counterpart.
 *
 * @param {string} relativePath e.g. 'assets/admin/settings.js'.
 * @return {string} e.g. 'assets/admin/settings.min.js'.
 */
function toMinifiedPath( relativePath ) {
	return relativePath.replace( /\.(css|js)$/, '.min.$1' );
}

/**
 * Minify one asset descriptor and write its `.min.*` file to disk.
 *
 * @param {{relativePath: string, type: 'js'|'css'}} asset Asset descriptor.
 * @param {string} rootDir Plugin root directory.
 * @return {Promise<string>} Absolute path of the written `.min.*` file.
 */
async function buildAsset( asset, rootDir ) {
	const sourcePath = path.join( rootDir, asset.relativePath );
	const source = fs.readFileSync( sourcePath, 'utf8' );
	const minified = 'js' === asset.type ? await minifyJs( source ) : minifyCss( source );
	const destinationPath = path.join( rootDir, toMinifiedPath( asset.relativePath ) );

	fs.writeFileSync( destinationPath, minified );

	return destinationPath;
}

/**
 * Build every known asset.
 *
 * @param {string} [rootDir] Plugin root directory, defaults to the repo root.
 * @return {Promise<string[]>} Absolute paths of every written `.min.*` file.
 */
async function buildAll( rootDir = path.resolve( __dirname, '..' ) ) {
	const outputs = [];

	for ( const asset of ASSETS ) {
		outputs.push( await buildAsset( asset, rootDir ) );
	}

	return outputs;
}

module.exports = { ASSETS, minifyJs, minifyCss, toMinifiedPath, buildAsset, buildAll };

if ( require.main === module ) {
	buildAll()
		.then( ( outputs ) => {
			outputs.forEach( ( file ) => {
				console.log( 'Built ' + path.relative( process.cwd(), file ) );
			} );
		} )
		.catch( ( error ) => {
			console.error( error );
			process.exitCode = 1;
		} );
}
